if (sm64ds_net::nonblocking(g_sock) != 0) {
    const int error = errno;
    ::close(g_sock); g_sock = -1;
    std::fprintf(stderr, "[comms:native] nonblocking socket failed (%d); idle\n", error);
    return;
}
// No SIO_UDP_CONNRESET equivalent is required for this unconnected POSIX UDP socket.

