double now_ms()
{
    static LARGE_INTEGER qpf;
    LARGE_INTEGER t;
    if (!qpf.QuadPart) QueryPerformanceFrequency(&qpf);
    QueryPerformanceCounter(&t);
    return t.QuadPart * 1000.0 / (double)qpf.QuadPart;
}
